{
  "commitMessage": "feat(contact): add contact page and register in E2E page list",
  "files": [
    {
      "path": "src/app/(crm)/contacto/page.tsx",
      "content": "import type { Metadata } from "next";
import { PageHeader } from "@/components/page-header";

export const metadata: Metadata = { title: "Contacto · crm-demo" };

export default function ContactPage() {
  return (
    <div data-testid="contact-page">
      <PageHeader
        title="Contacto"
        description="Información de contacto de nuestra empresa."
      />
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <div className="rounded-lg border border-slate-200 bg-white p-5 shadow-xs">
          <h2 className="text-xs font-semibold tracking-wider text-slate-500 uppercase">
            Correo electrónico
          </h2>
          <p className="mt-2 font-medium text-slate-900" data-testid="contact-email">
            contacto@crmdemo.es
          </p>
        </div>
        <div className="rounded-lg border border-slate-200 bg-white p-5 shadow-xs">
          <h2 className="text-xs font-semibold tracking-wider text-slate-500 uppercase">
            Teléfono
          </h2>
          <p className="mt-2 font-medium text-slate-900" data-testid="contact-phone">
            +34 912 345 678
          </p>
        </div>
        <div className="rounded-lg border border-slate-200 bg-white p-5 shadow-xs">
          <h2 className="text-xs font-semibold tracking-wider text-slate-500 uppercase">
            Horario de atención
          </h2>
          <p className="mt-2 font-medium text-slate-900">
            Lunes a Viernes: 9:00 - 18:00
          </p>
        </div>
      </div>
    </div>
  );
}
"
    },
    {
      "path": "e2e/pages.ts",
      "content": "/**
 * Pages captured by `screenshots.spec.ts` on every preview, at 1280 px
 * (desktop project) and 390 px (mobile-390 project). The files are named
 * `<name>-<width>.jpg`. To capture a new page, add one line.
 *
 * - `path`: a page reached directly.
 * - `fromList` + `rowTestId`: a detail page, opened from the first row of a
 *   list so it does not depend on database ids.
 */
export type CapturedPage =
  | { name: string; path: string }
  | { name: string; fromList: string; rowTestId: string };

export const pages: CapturedPage[] = [
  { name: "clientes", path: "/clientes" },
  { name: "presupuestos", path: "/presupuestos" },
  { name: "facturas", path: "/facturas" },
  { name: "contacto", path: "/contacto" },
  { name: "cliente-detalle", fromList: "/clientes", rowTestId: "client-row" },
  {
    name: "presupuesto-detalle",
    fromList: "/presupuestos",
    rowTestId: "quote-row",
  },
];
"
    }
  ],
  "notes": "He creado la página de contacto en src/app/(crm)/contacto/page.tsx incluyendo tarjetas estilizadas con Tailwind para email, teléfono y horario. He añadido los testids `contact-page`, `contact-email` y `contact-phone`. Además, he registrado la ruta `/contacto` en `e2e/pages.ts` para que se capturen screenshots en Playwright.",
  "evidence": [
    {
      "criterion": "c2",
      "hint": "La página /contacto incluye data-testid contact-page, contact-email y contact-phone, además de PageHeader con page-title."
    },
    {
      "criterion": "c3",
      "hint": "Añadida la entrada { name: 'contacto', path: '/contacto' } en e2e/pages.ts."
    }
  ]
}
